with open('/workdir/disk.img', 'rb') as f:
    data = f.read()

# Look for typical file content patterns - printable ASCII sequences
# Let's find regions with lots of printable characters
import re
# Look for sequences of printable text (ASCII 32-126)
text_regions = []
current_text_start = None
for i, b in enumerate(data):
    if 32 <= b <= 126:
        if current_text_start is None:
            current_text_start = i
    else:
        if current_text_start is not None:
            text_regions.append((current_text_start, i))
            current_text_start = None
if current_text_start is not None:
    text_regions.append((current_text_start, len(data)))

# Print the found text regions
for start, end in text_regions[:20]:  # First 20 regions
    chunk = data[start:end]
    try:
        text = chunk.decode('utf-8', errors='replace')
        print(f'Region at {start}-{end}:')
        print(text[:100])
        print('---')
    except:
        pass
